"use client";

import * as React from "react";

import { LearnerShell } from "@/registry/luma/blocks/learner-shell";

type CatalogCourse = {
  id: string;
  title: string;
  description: string;
  lessonCount: number;
};

type CatalogTopic = {
  id: string;
  title: string;
  lead?: string;
  pattern: "dots" | "lines" | "grid" | "rings";
  courses: CatalogCourse[];
};

const TOPICS: CatalogTopic[] = [
  {
    id: "reading",
    title: "읽기",
    lead: "문장과 단락에서 의미를 정확히 짚는 코스",
    pattern: "dots",
    courses: [
      {
        id: "vocab-meaning",
        title: "어휘와 문장의 의미 정확히 읽기",
        description: "문맥 단서로 낯선 어휘의 뜻을 추론하고, 문장 단위로 의미를 정리합니다.",
        lessonCount: 20,
      },
      {
        id: "paragraph-main",
        title: "단락의 중심 생각 찾기",
        description: "핵심 문장과 보조 정보를 구분해 단락이 말하는 바를 요약합니다.",
        lessonCount: 14,
      },
      {
        id: "inference-short",
        title: "짧은 글에서 추론하기",
        description: "명시되지 않은 관계를 글로 주어진 단서만으로 조심스럽게 읽습니다.",
        lessonCount: 12,
      },
    ],
  },
  {
    id: "speaking",
    title: "회화",
    lead: "일상 장면을 자연스럽게 말하는 코스",
    pattern: "lines",
    courses: [
      {
        id: "greetings",
        title: "인사와 자기소개",
        description: "처음 만나는 사람에게 인사하고 나를 짧게 소개하는 표현을 익힙니다.",
        lessonCount: 8,
      },
      {
        id: "daily-request",
        title: "부탁과 거절하기",
        description: "부탁·수락·거절의 톤을 상황에 맞게 고르고 이어 말하는 연습을 합니다.",
        lessonCount: 10,
      },
      {
        id: "ordering",
        title: "가게에서 주문하기",
        description: "메뉴 확인, 주문, 변경 요청처럼 짧은 대화를 순서대로 구성합니다.",
        lessonCount: 9,
      },
    ],
  },
  {
    id: "listening",
    title: "듣기",
    lead: "말의 흐름과 핵심을 잡는 코스",
    pattern: "grid",
    courses: [
      {
        id: "listen-gist",
        title: "대화의 요지 듣기",
        description: "세부보다 먼저 화자와 목적, 결론을 듣고 정리합니다.",
        lessonCount: 11,
      },
      {
        id: "listen-detail",
        title: "숫자와 시간 정보 듣기",
        description: "일정·가격·장소처럼 놓치기 쉬운 정보를 정확히 받아 적습니다.",
        lessonCount: 10,
      },
    ],
  },
  {
    id: "writing",
    title: "쓰기",
    lead: "짧은 문장을 또렷하게 쓰는 코스",
    pattern: "rings",
    courses: [
      {
        id: "sentence-build",
        title: "문장 뼈대 만들기",
        description: "주어·서술어·수식 관계를 정리해 짧고 분명한 문장을 씁니다.",
        lessonCount: 16,
      },
      {
        id: "message-reply",
        title: "메시지에 답장하기",
        description: "받은 메시지의 목적을 읽고, 예의와 정보가 맞는 답장을 작성합니다.",
        lessonCount: 12,
      },
      {
        id: "opinion-short",
        title: "짧은 의견 쓰기",
        description: "주장 한 문장과 근거 한 문장으로 의견을 또렷하게 남깁니다.",
        lessonCount: 13,
      },
    ],
  },
];

function CoursePattern({ pattern }: { pattern: CatalogTopic["pattern"] }) {
  return (
    <div
      data-slot="learn-catalog-pattern"
      className="relative aspect-[4/3] overflow-hidden rounded-[1.25rem] bg-muted"
      aria-hidden="true"
    >
      {pattern === "dots" ? (
        <div
          className="absolute inset-0 opacity-[0.35]"
          style={{
            backgroundImage:
              "radial-gradient(circle, color-mix(in oklch, var(--foreground) 28%, transparent) 1.1px, transparent 1.2px)",
            backgroundSize: "12px 12px",
          }}
        />
      ) : null}
      {pattern === "lines" ? (
        <div
          className="absolute inset-0 opacity-[0.28]"
          style={{
            backgroundImage:
              "repeating-linear-gradient(-18deg, color-mix(in oklch, var(--foreground) 22%, transparent) 0 1px, transparent 1px 10px)",
          }}
        />
      ) : null}
      {pattern === "grid" ? (
        <div
          className="absolute inset-0 opacity-[0.3]"
          style={{
            backgroundImage:
              "linear-gradient(color-mix(in oklch, var(--foreground) 18%, transparent) 1px, transparent 1px), linear-gradient(90deg, color-mix(in oklch, var(--foreground) 18%, transparent) 1px, transparent 1px)",
            backgroundSize: "16px 16px",
          }}
        />
      ) : null}
      {pattern === "rings" ? (
        <>
          <span className="absolute top-1/2 left-1/2 size-28 -translate-x-1/2 -translate-y-1/2 rounded-full border border-foreground/15" />
          <span className="absolute top-1/2 left-1/2 size-16 -translate-x-1/2 -translate-y-1/2 rounded-full border border-dashed border-foreground/20" />
          <span className="absolute top-[28%] left-[22%] size-3 rounded-full bg-foreground/12" />
        </>
      ) : null}
      <span className="absolute inset-3 rounded-[0.9rem] border border-border/50" />
    </div>
  );
}

function CourseCard({
  course,
  pattern,
}: {
  course: CatalogCourse;
  pattern: CatalogTopic["pattern"];
}) {
  return (
    <article
      data-slot="learn-catalog-course"
      className="flex flex-col gap-4 rounded-[1.75rem] bg-muted/55 p-4 sm:p-5"
    >
      <CoursePattern pattern={pattern} />
      <div className="flex min-w-0 flex-1 flex-col gap-2 px-0.5 pb-0.5">
        <h3 className="font-heading text-base font-semibold tracking-[-0.02em] text-balance">
          {course.title}
        </h3>
        <p className="line-clamp-2 text-sm leading-6 text-pretty text-muted-foreground">
          {course.description}
        </p>
        <p className="mt-auto pt-1 text-xs tabular-nums text-muted-foreground">
          {course.lessonCount}레슨
        </p>
      </div>
    </article>
  );
}

/**
 * Logged-in learner course catalog: topic sections with quiet pattern thumbnails.
 * Static list only — no search, filters, or course actions.
 */
export function LearnCatalog({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <LearnerShell data-slot="learn-catalog" className={className} currentNav="learn" {...props}>
      <main className="@container mx-auto flex w-full max-w-5xl flex-1 flex-col gap-12 px-5 py-10 sm:px-8 sm:py-12">
        <header
          data-slot="learn-catalog-intro"
          className="flex max-w-xl flex-col gap-2"
          aria-labelledby="learn-catalog-title"
        >
          <h1
            id="learn-catalog-title"
            className="font-heading text-3xl font-semibold tracking-[-0.04em] text-balance sm:text-4xl sm:leading-[1.15]"
          >
            코스
          </h1>
          <p className="text-sm leading-6 text-pretty text-muted-foreground sm:text-[0.9375rem]">
            주제별로 코스를 살펴보세요
          </p>
        </header>

        <div className="flex flex-col gap-14">
          {TOPICS.map((topic) => (
            <section
              key={topic.id}
              data-slot="learn-catalog-topic"
              aria-labelledby={`learn-catalog-topic-${topic.id}`}
              className="flex flex-col gap-5"
            >
              <header className="flex flex-col gap-1.5">
                <h2
                  id={`learn-catalog-topic-${topic.id}`}
                  className="font-heading text-xl font-semibold tracking-[-0.03em] sm:text-2xl"
                >
                  {topic.title}
                </h2>
                {topic.lead ? <p className="text-sm text-muted-foreground">{topic.lead}</p> : null}
              </header>

              <div className="grid grid-cols-[repeat(auto-fit,minmax(min(100%,15rem),1fr))] gap-3 @[40rem]:gap-4">
                {topic.courses.map((course) => (
                  <CourseCard key={course.id} course={course} pattern={topic.pattern} />
                ))}
              </div>
            </section>
          ))}
        </div>
      </main>
    </LearnerShell>
  );
}

export default LearnCatalog;

"use client";

import * as React from "react";
import { HugeiconsIcon } from "@hugeicons/react";
import { BookOpen01Icon, Logout03Icon, Settings02Icon, UserIcon } from "@hugeicons/core-free-icons";

import { cn } from "@/registry/luma/lib/utils";
import { Avatar, AvatarFallback } from "@/registry/luma/ui/avatar";
import { Button } from "@/registry/luma/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/registry/luma/ui/dropdown-menu";

export type LearnerNavId = "home" | "learn";

export type LearnerProfileAction = "profile" | "history" | "settings" | "logout";

const NAV_ITEMS: { id: LearnerNavId; href: string; label: string }[] = [
  { id: "home", href: "#home", label: "홈" },
  { id: "learn", href: "#learn", label: "학습" },
];

function preventNav(event: React.MouseEvent | React.SyntheticEvent) {
  event.preventDefault();
}

function LearnerShellHeader({
  currentNav,
  userName = "민지",
  userInitial = "민",
  onProfileAction,
}: {
  currentNav?: LearnerNavId | null;
  userName?: string;
  userInitial?: string;
  onProfileAction?: (action: LearnerProfileAction) => void;
}) {
  return (
    <header
      data-slot="learner-shell-header"
      className="sticky top-0 z-40 border-b border-border/50 bg-background/90 backdrop-blur-xl"
    >
      <div className="mx-auto flex h-14 w-full max-w-5xl items-center gap-2 px-4 @[40rem]/learner-shell:h-15 @[40rem]/learner-shell:gap-4 @[40rem]/learner-shell:px-8">
        <a
          href="#home"
          className="flex shrink-0 items-center gap-2 font-heading text-sm font-semibold tracking-[-0.02em] @[40rem]/learner-shell:gap-2.5"
          onClick={preventNav}
        >
          <span className="grid size-7 place-items-center rounded-xl bg-foreground text-[0.65rem] text-background">
            L
          </span>
          <span className="hidden @[28rem]/learner-shell:inline">Luma</span>
        </a>

        <nav
          className="ml-0.5 flex min-w-0 items-center gap-0.5 overflow-x-auto text-sm [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
          aria-label="글로벌 메뉴"
        >
          {NAV_ITEMS.map((item) => {
            const current = item.id === currentNav;
            return (
              <a
                key={item.id}
                href={item.href}
                aria-current={current ? "page" : undefined}
                className={cn(
                  "shrink-0 rounded-xl px-2.5 py-1.5 transition-colors @[40rem]/learner-shell:px-3",
                  current
                    ? "bg-muted font-medium text-foreground"
                    : "text-muted-foreground hover:bg-muted/70 hover:text-foreground",
                )}
                onClick={preventNav}
              >
                {item.label}
              </a>
            );
          })}
        </nav>

        <div className="ml-auto">
          <DropdownMenu>
            <DropdownMenuTrigger
              render={<Button variant="ghost" size="icon-sm" className="rounded-full" />}
              aria-label="프로필 메뉴 열기"
            >
              <Avatar size="sm">
                <AvatarFallback>{userInitial}</AvatarFallback>
              </Avatar>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="min-w-52">
              <DropdownMenuGroup>
                <DropdownMenuLabel>{userName}</DropdownMenuLabel>
                <DropdownMenuItem onClick={() => onProfileAction?.("profile")}>
                  <HugeiconsIcon icon={UserIcon} strokeWidth={2} />
                  프로필
                </DropdownMenuItem>
                <DropdownMenuItem onClick={() => onProfileAction?.("history")}>
                  <HugeiconsIcon icon={BookOpen01Icon} strokeWidth={2} />
                  학습 기록
                </DropdownMenuItem>
                <DropdownMenuItem onClick={() => onProfileAction?.("settings")}>
                  <HugeiconsIcon icon={Settings02Icon} strokeWidth={2} />
                  설정
                </DropdownMenuItem>
              </DropdownMenuGroup>
              <DropdownMenuSeparator />
              <DropdownMenuItem variant="destructive" onClick={() => onProfileAction?.("logout")}>
                <HugeiconsIcon icon={Logout03Icon} strokeWidth={2} />
                로그아웃
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </div>
    </header>
  );
}

/**
 * Shared chrome for logged-in learner surfaces (home, catalog, course detail, profile).
 * Lesson sessions use their own session chrome and should not use this shell.
 */
export function LearnerShell({
  className,
  currentNav = null,
  userName = "민지",
  userInitial = "민",
  onProfileAction,
  children,
  ...props
}: React.ComponentProps<"div"> & {
  currentNav?: LearnerNavId | null;
  userName?: string;
  userInitial?: string;
  onProfileAction?: (action: LearnerProfileAction) => void;
}) {
  return (
    <div
      data-slot="learner-shell"
      className={cn(
        "@container/learner-shell flex min-h-svh w-full flex-col bg-background",
        className,
      )}
      {...props}
    >
      <LearnerShellHeader
        currentNav={currentNav}
        userName={userName}
        userInitial={userInitial}
        onProfileAction={onProfileAction}
      />
      {children}
    </div>
  );
}

export default LearnerShell;
